export function evaluate({ inputs, time }) {
  const u = inputs.launchSpeed;
  const g = inputs.gravity;
  const m = inputs.mass;

  const tTop = u / g;
  const t = Math.min(time, 2 * tTop);

  const y = Math.max(0, u * t - 0.5 * g * t * t);
  const v = u - g * t;
  const a = -g;
  const Fg = m * g;

  let motionState = 'At the top';
  if (t === 0) {
    motionState = 'Ready to toss';
  } else if (Math.abs(t - tTop) < 0.015) {
    motionState = 'At the top';
  } else if (t < tTop) {
    motionState = 'Rising';
  } else if (t >= 2 * tTop - 0.001) {
    motionState = 'Back at launch height';
  } else {
    motionState = 'Falling';
  }

  const objects = [];

  // Left Lane: The motion
  const leftLane = sdk.panel({
    x: 20,
    y: 20,
    w: 290,
    h: 380,
    title: 'The motion',
    state: motionState,
    id: 'lane.motion'
  });
  objects.push(...leftLane);

  // Ruler Axis inside left panel (y runs UP from y=360 to y=60)
  // Ruler scale: 0 to 2.2 m
  const ruler = sdk.axis('axis.ruler', {
    x: 60,
    y: 360,
    length: 300,
    orientation: 'y',
    min: 0,
    max: 2.2,
    ticks: [0, 0.5, 1.0, 1.5, 2.0],
    label: 'Height',
    unit: 'm'
  });
  objects.push(ruler);

  // Map ball height (0 to 2.2m) to pixel y (360 down to 60)
  const ballY = 360 - (y / 2.2) * 300;
  const ballX = 140;

  // Ball circle (diameter 24)
  const ball = sdk.circle('ball.toss', ballX, ballY, 24);
  objects.push(ball);

  // Velocity Vector (blue, scaled)
  const vVec = sdk.vector('vec.v', { x: ballX + 25, y: ballY }, {
    value: v,
    direction: 'up',
    scale: 15,
    label: 'v'
  });
  objects.push(...vVec);

  // Acceleration Vector (dashed warm, constant -g)
  const aVec = sdk.vector('vec.a', { x: ballX - 25, y: ballY }, {
    value: a,
    direction: 'up',
    scale: 10,
    label: 'a'
  });
  objects.push(...aVec);

  // Callout beside ball
  const calloutLines = [
    `v = ${sdk.format(v, 2)} m/s`,
    `a = ${sdk.format(a, 2)} m/s²`,
    `Fg = ${sdk.format(Fg, 1)} N`
  ];
  const calloutObj = sdk.callout(ballX + 55, ballY - 20, calloutLines, { id: 'callout.toss' });
  objects.push(...calloutObj);

  // Right Lane: Velocity over time
  const rightLane = sdk.panel({
    x: 330,
    y: 20,
    w: 290,
    h: 380,
    title: 'Velocity over time',
    state: `t = ${sdk.format(t, 2)} s`,
    id: 'lane.vt'
  });
  objects.push(...rightLane);

  // Generate vt plot points
  const tracePoints = [];
  const samples = 20;
  for (let i = 0; i <= samples; i++) {
    const st = (i / samples) * t;
    const sv = u - g * st;
    tracePoints.push({ x: st, y: sv });
  }

  const plotVt = sdk.plot('plot.vt', {
    x: 345,
    y: 60,
    w: 260,
    h: 310,
    axes: {
      x: { label: 'Time', min: 0, max: 1.8, unit: 's' },
      y: { label: 'Velocity', min: -5.5, max: 5.5, unit: 'm/s' }
    },
    series: [
      {
        label: 'v = u - g t',
        kind: 'line',
        points: tracePoints
      }
    ]
  });
  objects.push(plotVt);

  return {
    frame: sdk.frame(objects, { width: 640, height: 420 }),
    quantities: {
      launchSpeed: u,
      gravity: g,
      mass: m,
      apexTime: tTop,
      apexHeight: (u * u) / (2 * g),
      height: y,
      velocity: v,
      acceleration: a,
      force: Fg
    },
    readouts: [
      { id: 'velocity', value: v },
      { id: 'acceleration', value: a },
      { id: 'force', value: Fg },
      { id: 'motionState', value: motionState }
    ]
  };
}
